import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.CameraShake{Intensity: 0.5, Duration: 2, Type: 1, Action: 0}
CAMERA_SHAKE = bytes.fromhex("0000003f000000400100")

GOLDENS = [
    pytest.param(
        v2225.CameraShakePacket(
            intensity=0.5,
            seconds=2.0,
            shake_type=v2225.CameraShakeType.ROTATIONAL,
            shake_action=v2225.CameraShakeAction.ADD,
        ),
        CAMERA_SHAKE,
        id="rotational-add",
    ),
]

STOPPING_SHAKE = v2225.CameraShakePacket(
    shake_type=v2225.CameraShakeType.POSITIONAL, shake_action=v2225.CameraShakeAction.STOP
)


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_camera_shake_is_packet_159(version):
    assert version.PACKETS[159] is version.CameraShakePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_camera_shake_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_camera_shake_decodes_from_its_golden(packet, golden):
    assert v2225.CameraShakePacket.from_bytes(golden) == packet


def test_both_shake_enums_are_one_byte_so_the_body_is_ten_bytes():
    assert len(bytes(STOPPING_SHAKE)) == 10


def test_the_shake_action_is_the_last_byte():
    assert bytes(STOPPING_SHAKE)[-1] == 1


def test_decode_rejects_a_shake_one_byte_short():
    with pytest.raises(ValueError, match="at byte"):
        v2225.CameraShakePacket.from_bytes(bytes(STOPPING_SHAKE)[:9])
